$(document).ready(function(){$("#checkCoupon").click(function(e){e.preventDefault(),console.log("i m here to check coupon")}),$("#addToCart").click(function(e){e.preventDefault(),$("#addToCart").hide();var t=$("#qty").val().split("_"),o=t[0],c=t[2];t=t[1];$.ajax({type:"POST",dataType:"json",data:{id:o,quantity:t,price:c,type:"cart",action:"add"},success:function(e){$("#addToCart").show(),200==e.status?($("#cartNumber").html(1),$("#cartNumber").css({background:"#219518",color:"#fff"}),$("#addToCardPopUp").show(),$("#selectedName").text(""),$("#selectedName").append(e.productName),$("#selectedImg").text(""),$("#selectedImg").attr("src",e.productImage),$("#selectedQty").text(""),$("#selectedQty").append(e.productQty)):console.log(e.msg)},error:function(e){console.log(e),$("#addToCart").show()}})}),$("#closeAddToCartPopUp").click(function(e){e.preventDefault(),$("#addToCardPopUp").hide()}),$("#removeFromCart").click(function(e){e.preventDefault(),$("#addToCardPopUp").hide()})});